import os, json; import google.generativeai as genai; from dotenv import load_dotenv; load_dotenv(); genai.configure(api_key=os.getenv('GEMINI_API_KEY')); gemini_model = genai.GenerativeModel('gemini-3.5-flash', generation_config={'response_mime_type': 'application/json'}); print(repr(gemini_model.generate_content('你是一個行事曆秘書。你的任務是從使用者的輸入中擷取會議或行程的三個要素：1. topic 2. time 3. location。目前已經收集到的資訊 (若為null代表尚未提供)：{\"topic\": null, \"time\": null, \"location\": null}。使用者的最新輸入是：「我星期一下午5點56分要去健身」。必須只回傳符合格式的 JSON 字串。').text))
